   126→          "images",
   127→          String(timestamp)
   128→        );
   129→        await fs.mkdir(tempImageDir, { recursive: true });
   130→
   131→        sessionData.tempImageDir = tempImageDir;
   132→
   133→        // Save images to temp directory
   134→        for (let i = 0; i < messageData.images.length; i++) {
   135→          const image = messageData.images[i];
   136→
   137→          // Extract file extension from base64 data URL or use default
   138→          let ext = ".png";
   139→          if (image.startsWith("data:image/")) {
   140→            const mimeType = image.split(";")[0].split("/")[1];
   141→            ext = "." + mimeType;
   142→          }
   143→
   144→          const imagePath = path.join(tempImageDir, `image-${i}${ext}`);
   145→
   146→          // If image is base64, decode and save
   147→          if (image.startsWith("data:")) {
   148→            const base64Data = image.split(",")[1];
   149→            await fs.writeFile(imagePath, Buffer.from(base64Data, "base64"));
   150→          } else {
   151→            // Assume it's already a file path
   152→            await fs.copyFile(image, imagePath);
   153→          }
   154→
   155→          imagePaths.push(imagePath);
   156→        }
   157→      }
   158→
   159→      // Send message via agent-cli-sdk
   160→      try {
   161→        fastify.log.info(
   162→          { sessionId, messageLength: messageData.message.length },
   163→          "[WebSocket] Sending message to agent-cli-sdk"
   164→        );
   165→
   166→        const response = await sessionData.adapter.execute(
   167→          messageData.message,
   168→          {
   169→            sessionId,
   170→            resume: !!session.claudeSessionId, // Resume existing session
   171→            images: imagePaths.length > 0 ? imagePaths : undefined,
   172→            onOutput: (outputData: unknown) => {
   173→              // Stream output back to client with flat event name
   174→              sendMessage(socket, `session.${sessionId}.stream_output`, {
   175→                content: outputData,
   176→              });
   177→            },
   178→            verbose: true,
   179→            ...messageData.config,
   180→          }
   181→        );
   182→
   183→        fastify.log.info({ sessionId }, "[WebSocket] Received response from agent-cli-sdk");
   184→
   185→        // Check if the response indicates an error
   186→        if (response.status === "error") {
   187→          fastify.log.error({ sessionId, response }, "Agent CLI SDK returned error status");
   188→
   189→          // Clean up temp images on error
   190→          if (sessionData.tempImageDir) {
   191→            try {
   192→              await fs.rm(sessionData.tempImageDir, { recursive: true, force: true });
   193→              sessionData.tempImageDir = undefined;
   194→            } catch (cleanupErr) {
   195→              fastify.log.warn({ err: cleanupErr }, "Failed to clean up temp images");
   196→            }
   197→          }
   198→
   199→          // Send error message to client
   200→          sendMessage(socket, `session.${sessionId}.error`, {
   201→            error: response.data || "An error occurred",
   202→            message: response.data || "An error occurred while processing your request",
   203→            details: {
   204→              exitCode: response.exitCode,
   205→              stderr: response.raw?.stderr,
   206→              stdout: response.raw?.stdout,
   207→              duration: response.duration,
   208→            },
   209→          });
   210→          return;
   211→        }
   212→
   213→        // After message completes, update session metadata
   214→        let metadata = null;
   215→        try {
   216→          const jsonlPath = getSessionFilePath(
   217→            sessionData.projectPath,
   218→            sessionId
