   220→          metadata = await parseJSONLFile(jsonlPath);
   221→
   222→          await updateSessionMetadata(sessionId, metadata);
   223→        } catch (metadataErr: unknown) {
   224→          // JSONL file might not exist yet for new sessions or parsing failed
