   243→        //       '[WebSocket] Generating session name from first user message'
   244→        //     );
   245→        //
   246→        //     const sessionName = await generateSessionName({
   247→        //       userPrompt: messageData.message,
   248→        //     });
   249→        //
   250→        //     // Update session with generated name
   251→        //     await prisma.agentSession.update({
   252→        //       where: { id: sessionId },
   253→        //       data: { name: sessionName },
   254→        //     });
   255→        //
   256→        //     fastify.log.info(
   257→        //       { sessionId, sessionName },
   258→        //       '[WebSocket] Session name generated successfully'
   259→        //     );
   260→        //   } catch (nameErr: unknown) {
   261→        //     // Don't fail message completion if name generation fails
   262→        //     fastify.log.warn(
   263→        //       { err: nameErr, sessionId },
   264→        //       '[WebSocket] Failed to generate session name (non-critical)'
   265→        //     );
   266→        //   }
   267→        // }
   268→        // ============= END SESSION NAME GENERATION =============
   269→
   270→        // Extract usage data from the last assistant message in response.events
   271→        let usage = null;
   272→        if (response.events && Array.isArray(response.events)) {
   273→          const events = response.events;
   274→          fastify.log.info({ dataLength: events.length, sessionId }, "Extracting usage from response.events");
   275→
   276→          // Log the last few events to understand the structure
   277→          const lastEvents = events.slice(-3);
   278→          fastify.log.info({ lastEvents: JSON.stringify(lastEvents, null, 2), sessionId }, "Last 3 events in response.events");
   279→
   280→          // Find the last assistant message with usage data
   281→          for (let i = events.length - 1; i >= 0; i--) {
   282→            const event = events[i];
   283→
   284→            // Log each event type we're checking
   285→            fastify.log.debug({
   286→              eventType: event.type,
   287→              eventRole: event.role,
   288→              hasUsage: !!event.usage,
   289→              hasMessageUsage: !!event.message?.usage,
   290→              eventKeys: Object.keys(event),
   291→              sessionId
   292→            }, "Checking event for usage");
   293→
   294→            if ((event.type === 'assistant' || event.role === 'assistant') && event.usage) {
   295→              usage = {
   296→                input_tokens: event.usage.input_tokens || 0,
   297→                output_tokens: event.usage.output_tokens || 0,
   298→              };
   299→              fastify.log.info({ usage, sessionId }, "Found usage in event.usage");
   300→              break;
   301→            }
   302→            // Also check event.message.usage for Claude CLI format
   303→            if ((event.type === 'assistant' || event.role === 'assistant') && event.message?.usage) {
   304→              usage = {
   305→                input_tokens: event.message.usage.input_tokens || 0,
   306→                output_tokens: event.message.usage.output_tokens || 0,
   307→              };
   308→              fastify.log.info({ usage, sessionId }, "Found usage in event.message.usage");
   309→              break;
   310→            }
   311→          }
   312→
   313→          if (!usage) {
   314→            fastify.log.warn({ sessionId, lastEvent: events[events.length - 1] }, "No usage data found in response.events");
   315→          }
   316→        } else {
   317→          fastify.log.warn({ sessionId, responseKeys: response ? Object.keys(response) : null }, "response.events is not an array or doesn't exist");
   318→        }
   319→
   320→        // Clean up temporary images
   321→        if (sessionData.tempImageDir) {
   322→          try {
   323→            await fs.rm(sessionData.tempImageDir, { recursive: true, force: true });
