   349→          }
   350→        }
   351→
   352→        // Send detailed error information to frontend
   353→        const errorMessage = err instanceof Error ? err.message : "Failed to send message";
   354→        const errorStack = err instanceof Error ? err.stack : undefined;
   355→        const errorName = err instanceof Error ? err.name : undefined;
   356→        const errorDetails = typeof err === 'object' && err !== null
   357→          ? (err as Record<string, unknown>).response || (err as Record<string, unknown>).data
   358→          : undefined;
   359→
   360→        sendMessage(socket, `session.${sessionId}.error`, {
   361→          error: errorMessage,
   362→          message: errorMessage,
   363→          stack: errorStack,
   364→          name: errorName,
   365→          details: errorDetails,
   366→        });
   367→      }
   368→    } else {
