   390→// ============= SHELL HANDLERS =============
   391→
   392→/**
   393→ * Handle shell events (shell.{id}.action)
   394→ */
   395→async function handleShellEvent(
   396→  socket: WebSocket,
   397→  type: string,
   398→  _data: unknown,
   399→  _userId: string,
   400→  fastify: FastifyInstance
   401→): Promise<void> {
   402→  const shellId = extractId(type, 'shell');
   403→  if (!shellId) {
   404→    sendMessage(socket, 'global.error', {
   405→      error: 'Invalid shell event type',
   406→      message: `Expected format: shell.{id}.action, got: ${type}`,
   407→    });
   408→    return;
   409→  }
   410→
   411→  // TODO: Implement shell functionality when ready
   412→  // For now, just send a not implemented message
   413→  fastify.log.info({ type, shellId }, '[WebSocket] Shell event received (not implemented yet)');
   414→  sendMessage(socket, `shell.${shellId}.error`, {
   415→    error: 'Shell functionality not implemented',
   416→    message: 'Shell/terminal features are not yet implemented',
   417→  });
   418→}
   419→
   420→// ============= MAIN REGISTRATION =============
   421→
   422→/**
   423→ * Register unified WebSocket endpoint
   424→ */
   425→export async function registerWebSocket(fastify: FastifyInstance): Promise<void> {
   426→  fastify.register(async (fastify) => {
   427→    // Unified WebSocket endpoint with JWT authentication
   428→    fastify.get("/ws", { websocket: true }, async (socket, request) => {
   429→      let userId: string | null = null;
   430→
   431→      try {
   432→        fastify.log.info("[WebSocket] New connection attempt");
   433→
   434→        // Authenticate the WebSocket connection using JWT
   435→        try {
   436→          // Get token from query params (browser WebSocket doesn't support custom headers)
   437→          const query = request.query as { token?: string };
   438→          const token = query.token || request.headers.authorization?.replace("Bearer ", "");
   439→
   440→          if (!token) {
   441→            sendMessage(socket, 'global.error', {
   442→              error: 'Authentication required',
   443→              message: 'No authentication token provided',
   444→            });
   445→            socket.close(1008, 'Authentication required'); // 1008 = Policy Violation
   446→            return;
   447→          }
   448→
   449→          // Verify JWT token
   450→          const decoded = fastify.jwt.verify<JWTPayload>(token);
   451→          userId = decoded.userId;
   452→
   453→          fastify.log.info({ userId }, "[WebSocket] Client authenticated");
   454→
   455→          // Send global.connected event to signal client is ready
   456→          sendMessage(socket, 'global.connected', {
   457→            timestamp: Date.now(),
   458→            userId,
   459→          });
   460→        } catch (err: unknown) {
   461→          fastify.log.error({ err }, "[WebSocket] Authentication failed");
   462→          const errorMessage = err instanceof Error ? err.message : 'Invalid or expired token';
   463→          sendMessage(socket, 'global.error', {
   464→            error: 'Authentication failed',
   465→            message: errorMessage,
   466→          });
   467→          socket.close(1008, 'Authentication failed'); // 1008 = Policy Violation
   468→          return;
   469→        }
   470→
   471→        // Handle incoming messages
   472→        socket.on("message", async (message: Buffer | ArrayBuffer | Buffer[]) => {
   473→          try {
   474→            const messageStr = Buffer.isBuffer(message)
   475→              ? message.toString()
   476→              : Array.isArray(message)
   477→              ? Buffer.concat(message).toString()
   478→              : new TextDecoder().decode(message);
   479→
   480→            const parsed: WebSocketMessage = JSON.parse(messageStr);
   481→            const { type, data } = parsed;
   482→
   483→            fastify.log.info({ type, userId }, "[WebSocket] Received message");
   484→
   485→            // Route based on event type prefix
   486→            if (type.startsWith('session.')) {
   487→              await handleSessionEvent(socket, type, data, userId!, fastify);
   488→            } else if (type.startsWith('shell.')) {
   489→              await handleShellEvent(socket, type, data, userId!, fastify);
   490→            } else if (type.startsWith('global.')) {
   491→              // Global events from client (if any needed in future)
   492→              fastify.log.info({ type }, "[WebSocket] Global event received (no handler)");
   493→            } else {
   494→              // Unknown event type
   495→              sendMessage(socket, 'global.error', {
   496→                error: 'Unknown event type',
   497→                message: `Event type must start with 'session.', 'shell.', or 'global.': ${type}`,
   498→              });
   499→            }
   500→          } catch (err: unknown) {
   501→            fastify.log.error({ err }, "[WebSocket] Error processing message");
   502→            const errorMessage = err instanceof Error ? err.message : 'Malformed message';
   503→            sendMessage(socket, 'global.error', {
   504→              error: 'Failed to process message',
   505→              message: errorMessage,
   506→            });
   507→          }
   508→        });
   509→
   510→        // Handle disconnection
   511→        socket.on("close", () => {
   512→          fastify.log.info({ userId }, "[WebSocket] Client disconnected");
   513→
   514→          // Clean up active sessions for this user
   515→          for (const [_sessionId, sessionData] of activeSessions.entries()) {
   516→            if (sessionData.userId === userId) {
   517→              // Clean up temp images if any
   518→              if (sessionData.tempImageDir) {
   519→                fs.rm(sessionData.tempImageDir, { recursive: true, force: true }).catch(
   520→                  (err) => {
   521→                    fastify.log.warn({ err }, "Failed to clean up temp images on disconnect");
   522→                  }
   523→                );
   524→              }
   525→
   526→              // Note: We don't delete the session from activeSessions immediately
   527→              // to allow resume if user reconnects. Could add TTL logic here.
   528→            }
   529→          }
   530→        });
   531→
   532→        // Handle errors
   533→        socket.on("error", (err: Error) => {
   534→          fastify.log.error({ err, userId }, "[WebSocket] Socket error");
   535→
   536→          // Clean up on error
   537→          for (const [_sessionId, sessionData] of activeSessions.entries()) {
   538→            if (sessionData.userId === userId && sessionData.tempImageDir) {
   539→              fs.rm(sessionData.tempImageDir, { recursive: true, force: true }).catch(
   540→                (cleanupErr) => {
   541→                  fastify.log.warn({ err: cleanupErr }, "Failed to clean up temp images on error");
   542→                }
   543→              );
   544→            }
   545→          }
   546→        });
   547→      } catch (err) {
   548→        fastify.log.error({ err }, "[WebSocket] Fatal error in WebSocket handler");
   549→        socket.close();
   550→      }
   551→    });
   552→  });
   553→}
